/******/ (() => { // webpackBootstrap
var __webpack_exports__ = {};
/*!**********************************!*\
  !*** ./assets/scripts/editor.js ***!
  \**********************************/
jQuery(window).ready(function () {
  var wrapper;
  var sidebar;
  var sidebarButton;
  var sidebarWidth;
  setTimeout(function () {
    wrapper = jQuery('.edit-post-layout, .edit-site-layout');
    sidebar = jQuery('.interface-interface-skeleton__sidebar');
    sidebarButton = jQuery('[aria-controls="edit-post:document"][aria-expanded]');
    sidebarWidth = localStorage.getItem('bb_editor_sidebar_width') ? localStorage.getItem('bb_editor_sidebar_width') : 280;

    // Set sidebar width

    sidebar.width(sidebarWidth);

    // Check sidebar display status

    if (sidebarButton.attr('aria-expanded') == 'true') {
      wrapper.addClass('sidebar-open');
    }

    // Show hide sidebar

    jQuery('body').on('click', '[aria-controls="edit-post:document"]', function () {
      wrapper.toggleClass('sidebar-open');
    });

    // Show resizable toggles on sidebar

    sidebar.resizable({
      handles: 'w',
      resize: function resize(event, ui) {
        jQuery(this).css({
          'left': 0
        });
        localStorage.setItem('bb_editor_sidebar_width', jQuery(this).width());
      }
    });
  }, 500);
});
/******/ })()
;